from ta_emss.utilities.FSM_Configurator import FSM_Configurator


class RuffConfigurator(FSM_Configurator):

    def __init__(self, enb_device, config_plan, name, send=True, activate=False):
        super(RuffConfigurator, self).__init__(enb_device.ute_emss, send=send, activate=activate)
        self.enb = enb_device
        self.config_plan = self.transform_config_plan(config_plan)
        self.name = name

    def configure(self):
        self.enb.log_print("+++ Configure by RUFF (%s):" % self.name)
        self.enb.log_print("[%s]." % str(self.config_plan))
        return super(RuffConfigurator, self).configure(self.config_plan)

    def deconfigure(self):
        self.enb.log_print("--- Deconfigure by RUFF (%s)." % self.name)
        return super(RuffConfigurator, self).deconfigure()

    def transform_config_plan(self, config_plan):
        config_plan_transformed = {}
        for plan_entry in config_plan:
            moi = None
            if 'DEL' in plan_entry:
                entry_key = plan_entry.pop('DEL', None)
                entry_id = plan_entry.pop('ID', None)
                moi = "{}-{}".format(entry_key, entry_id)
                config_plan_transformed[moi] = None
            else:
                entry_key = plan_entry.pop('MOC', None)
                entry_id = plan_entry.pop('ID', None)
                moi = "{}-{}".format(entry_key, entry_id)
                if 'DN' in plan_entry:
                    entry_dn = plan_entry.pop('DN', None)
                    if 'DN' not in config_plan_transformed:
                        config_plan_transformed['DN'] = {}
                    if entry_dn is not None:
                        config_plan_transformed['DN'][moi] = entry_dn
                if moi not in config_plan_transformed:
                    config_plan_transformed[moi] = {}
                for attr in plan_entry:
                    config_plan_transformed[moi][attr] = plan_entry[attr]
        return config_plan_transformed
